def transform(grid):
    out=[row[:] for row in grid]
    n,m=len(grid),len(grid[0])
    squares=[]
    for r in range(n-2):
        for c in range(m-2):
            color=grid[r][c]
            if color and all(grid[i][j]==color for i in range(r,r+3) for j in range(c,c+3)):
                squares.append((r+1,c+1,color))
    marks={}
    for r,c,color in squares:
        for j in range(m): marks.setdefault((r,j),set()).add(color)
        for i in range(n): marks.setdefault((i,c),set()).add(color)
    for (i,j), colors in marks.items():
        if len(colors)>1:
            out[i][j]=0
        elif grid[i][j]==0:
            out[i][j]=next(iter(colors))
    return out
